package com.samlscope.runner.result;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

/** Self-contained offline report. Target-controlled strings are inserted only with textContent. */
public final class ReportHtmlWriter {
    private final String softwareLicenseBase64;
    private final String licensingScopeBase64;
    private final String sourceNoticesBase64;

    public ReportHtmlWriter(byte[] softwareLicense, byte[] licensingScope, byte[] sourceNotices) {
        this.softwareLicenseBase64 = encoded(softwareLicense, "softwareLicense");
        this.licensingScopeBase64 = encoded(licensingScope, "licensingScope");
        this.sourceNoticesBase64 = encoded(sourceNotices, "sourceNotices");
    }

    public byte[] write(byte[] resultJson) {
        if (resultJson == null || resultJson.length == 0) {
            throw new IllegalArgumentException("resultJson must not be empty");
        }
        var encoded = Base64.getEncoder().encodeToString(resultJson);
        return html(encoded, hasAttribution(resultJson)).getBytes(StandardCharsets.UTF_8);
    }

    private String html(String encodedJson, boolean hasAttribution) {
        return """
                <!doctype html>
                <html lang="en"><head><meta charset="utf-8">
                <meta name="viewport" content="width=device-width,initial-scale=1">
                <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'">
                <title>SAMLscope Conformance Test Result</title>
                <style>
                :root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#17202a;background:#f4f1ea}body{margin:0}main{max-width:1060px;margin:auto;padding:48px 24px 80px}h1{font-size:clamp(2rem,5vw,4rem);margin:.1em 0}.eyebrow{text-transform:uppercase;letter-spacing:.15em;color:#52606d;font-size:.78rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.card{background:#fff;border:1px solid #d9d4ca;border-radius:12px;padding:20px;box-shadow:0 8px 28px #0000000a}.value{font-size:1.35rem;font-weight:750;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;padding:10px;border-bottom:1px solid #e5e0d7}th{font-size:.75rem;text-transform:uppercase;letter-spacing:.08em}details{margin:16px 0}.statement,.notice-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.notice-text{font:inherit;font-size:.82rem;max-height:36rem;overflow:auto}.warning{color:#8a3b12}footer{margin-top:40px;color:#52606d;font-size:.9rem}@media print{body{background:#fff}.card{box-shadow:none}main{padding:0}}
                </style></head><body><main>
                <p class="eyebrow">Conformance test result</p><h1>SAMLscope</h1>
                <section class="grid" id="summary"></section>
                <section class="card"><h2>Conformance statement</h2><p class="statement" id="statement"></p></section>
                <section><h2>Requirements</h2><table><thead><tr><th>Requirement</th><th>Verdict</th><th>Obligations</th><th>Cases</th></tr></thead><tbody id="requirements"></tbody></table></section>
                <details><summary>Embedded authoritative result.json</summary><pre id="json"></pre></details>
                <section class="card"><h2>Licenses and sources</h2><p>The software license and retained specification notices travel with this standalone report.</p>
                <details><summary>Licensing scope</summary><pre class="notice-text" id="licensing-scope"></pre></details>
                <details><summary>Apache License, Version 2.0</summary><pre class="notice-text" id="software-license"></pre></details>
                <details><summary>Retained specification notices</summary><div id="source-notices"></div></details></section>
                <footer>This is a test result, not a certification. Product identity is self-declared. Generated by SAMLscope.</footer>
                </main><script>
                'use strict';const decode=value=>new TextDecoder().decode(Uint8Array.from(atob(value),c=>c.charCodeAt(0)));const text=decode('__SAMLSCOPE_RESULT_BASE64__');const r=JSON.parse(text);
                const add=(label,value,extra='')=>{const e=document.createElement('article');e.className='card';const l=document.createElement('p');l.className='eyebrow';l.textContent=label;const v=document.createElement('p');v.className='value '+extra;v.textContent=String(value);e.append(l,v);document.querySelector('#summary').append(e)};
                add('Conformance',r.run.conformance,r.run.conformance==='NON_CONFORMANT'?'warning':'');add('Completeness',r.run.completeness);add('Resolved MUST',`${r.coverage.must_resolved} / ${r.coverage.must_observable}`);add('Target',`${r.target.declared_product} (self-declared)`);add('Profile',r.profile.id);add('Request signing',r.configuration?.parameters?.request_signing_mode ?? 'Not recorded');add('Evaluation bundle',r.evaluation_bundle.digest);
                document.querySelector('#statement').textContent=r.conformance_statement;const tbody=document.querySelector('#requirements');for(const item of r.requirements){const tr=document.createElement('tr');for(const value of [item.id,item.verdict,item.obligations.length,item.cases.length]){const td=document.createElement('td');td.textContent=String(value);tr.append(td)}tbody.append(tr)}document.querySelector('#json').textContent=JSON.stringify(r,null,2);document.querySelector('#licensing-scope').textContent=decode('__SAMLSCOPE_LICENSING_SCOPE_BASE64__');document.querySelector('#software-license').textContent=decode('__SAMLSCOPE_SOFTWARE_LICENSE_BASE64__');
                const attribution=r.attribution ?? JSON.parse(decode('__SAMLSCOPE_SOURCE_NOTICES_BASE64__'));
                const notices=document.querySelector('#source-notices');
                const paragraph=(parent,tag,text)=>{const e=document.createElement(tag);e.textContent=text;parent.append(e);return e};
                if(attribution.scope)paragraph(notices,'p',attribution.scope);
                if(attribution.original_content_attribution)paragraph(notices,'p',attribution.original_content_attribution);
                if(attribution.modifications)paragraph(notices,'p',attribution.modifications);
                if(attribution.original_content_license_text){const d=document.createElement('details');paragraph(d,'summary','CC BY-SA 4.0 — original content only');paragraph(d,'pre',attribution.original_content_license_text).className='notice-text';notices.append(d)}
                for(const source of attribution.sources ?? []){paragraph(notices,'h3',`${source.title} — ${source.edition}`);if(/^https?:[/][/]/.test(source.source_url ?? '')){const a=paragraph(notices,'a','Original specification');a.href=source.source_url}paragraph(notices,'pre',source.notice_text).className='notice-text';if(source.terms_review_status?.startsWith('PENDING'))paragraph(notices,'p','Supplemental historical permission terms remain under review.')}
                for(const source of attribution.unresolved_sources ?? [])paragraph(notices,'p',`${typeof source==='string'?source:source.id}: source notice review pending`);
                if(attribution.unmapped_obligations?.length)paragraph(notices,'p',`Source mapping unavailable: ${attribution.unmapped_obligations.join(', ')}`);

                </script></body></html>
                """
                .replace("__SAMLSCOPE_RESULT_BASE64__", encodedJson)
                .replace("__SAMLSCOPE_LICENSING_SCOPE_BASE64__", licensingScopeBase64)
                .replace("__SAMLSCOPE_SOFTWARE_LICENSE_BASE64__", softwareLicenseBase64)
                .replace("__SAMLSCOPE_SOURCE_NOTICES_BASE64__", hasAttribution ? "e30=" : sourceNoticesBase64);
    }

    private static boolean hasAttribution(byte[] json) {
        try {
            var tree = new com.fasterxml.jackson.databind.ObjectMapper().readTree(json);
            return tree != null && tree.path("attribution").isObject();
        } catch (java.io.IOException e) {
            throw new IllegalArgumentException("Invalid result JSON", e);
        }
    }

    private static String encoded(byte[] value, String name) {
        if (value == null || value.length == 0) throw new IllegalArgumentException(name + " must not be empty");
        return Base64.getEncoder().encodeToString(value);
    }
}
